    # At row center_r:   cols center_c-1, center_c, center_c+1
    # At row center_r+1:  cols center_c, center_c+1  
    # At row center_r+2:  col center_c

    pattern = [
        [0, 1, 1, 0],      # relative offset 0
        [1, 1, 1, 0],      # relative offset 1
        [0, 1, 1, 0],      # relative offset 2
        [0, 0, 1, 0],      # relative offset 3
    ]

    for dr, row_pattern in enumerate(pattern):
