def apply_X_pattern(output_grid, tr, tc, color):
    """
    Apply X/cross pattern for 2x2 block with top-left at (tr, tc)
    Pattern spans rows tr-1 to tr+2
    """
    # Row offsets relative to tr
    patterns = {
        -1: [tc, tc+1],      # top part of X
        0:  [tc+1],          # middle left side
        1:  [tc-1, tc, tc+1, tc+2],  # full bar
        2:  [tc+1],          # bottom right side
    }

    for offset, cols in patterns.items():
        nr = tr + offset
        for nc in cols:
            if 0 <= nr < h and 0 <= nc < w:
                output_grid[nr][nc] = color

