def build_output_from_blocks(input_grid):
    H, W = len(input_grid), len(input_grid[0])
    output = [[0]*W for _ in range(H)]

    # Find each 2x2 block
    blocks = {}
    for c in range(W):
        for r in range(H):
            val = input_grid[r][c]
            if val != 0 and val != 8:  # not empty or wall
                if val not in blocks:
                    blocks[val] = []
                blocks[val].append((r, c))

    # For each color, find top-left corner
    for color, positions in sorted(blocks.items()):
        tr, tc = min(p[0] for p in positions), min(p[1] for p in positions)
        print(f"Applying color {color} block at ({tr}, {tc})...")

        # Apply pattern starting from row -1
        for offset in [-1, 0, 1, 2]:
            if offset == -1:
                # Extend up one row
                for c_offset in [0, 1]:
                    nr, nc = tr + offset, tc + c_offset
                    if 0 <= nr < H and 0 <= nc < W and input_grid[nr][nc] != 8:
                        output[nr][nc] = color
            elif offset == 0:
                # Middle row - single cell at center-right
                for c_offset in [1]:
                    nr, nc = tr + offset, tc + c_offset
                    if 0 <= nr < H and 0 <= nc < W and input_grid[nr][nc] != 8:
                        output[nr][nc] = color
            elif offset == 1:
                # Full horizontal bar
                for c_offset in [-1, 0, 1, 2]:
                    nr, nc = tr + offset, tc + c_offset
                    if 0 <= nr < H and 0 <= nc < W:
                        output[nr][nc] = color
            elif offset == 2:
                # Bottom row - single cell
                for c_offset in [1]:
                    nr, nc = tr + offset, tc + c_offset
                    if 0 <= nr < H and 0 <= nc < W:
                        output[nr][nc] = color

    return output

